BEGIN;
SET LOCAL lock_timeout='5s';
LOCK TABLE products,product_types,product_images,product_variants IN SHARE ROW EXCLUSIVE MODE;
CREATE TABLE catalog_decor_category_000042(category_id INTEGER PRIMARY KEY REFERENCES product_types(id) ON DELETE CASCADE);
CREATE TABLE catalog_decor_seed_000042(
 product_id INTEGER PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE,
 import_key TEXT NOT NULL UNIQUE,
 product_snapshot JSONB,
 images_snapshot JSONB
);
DO $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM brands WHERE name='Box Enxovais') THEN
  RAISE EXCEPTION 'Marca Box Enxovais ausente; cadastro interrompido.';
 END IF;
END $$;
WITH created AS (
 INSERT INTO product_types(name) SELECT 'Decoração' WHERE NOT EXISTS(SELECT 1 FROM product_types WHERE name='Decoração')
 RETURNING id
) INSERT INTO catalog_decor_category_000042 SELECT id FROM created;
