), inserted AS (
 INSERT INTO products(name,description,purchase_summary,care_instructions,measurements,price,quantity,brand_id,product_type_id,status)
 SELECT a.name,a.description,a.summary,a.care,a.attributes::jsonb,a.price,a.quantity,b.id,t.id,'active'
 FROM approved a CROSS JOIN brands b CROSS JOIN product_types t
 WHERE b.name='Box Enxovais' AND t.name='Decoração'
 AND NOT EXISTS(SELECT 1 FROM products p WHERE p.name=a.name OR p.measurements->>'catalog_import_key'=a.attributes::jsonb->>'catalog_import_key')
 ORDER BY a.name RETURNING id,measurements->>'catalog_import_key' AS import_key
) INSERT INTO catalog_decor_seed_000042(product_id,import_key) SELECT id,import_key FROM inserted;
INSERT INTO product_images(product_id,image_path,is_primary,alt_text)
SELECT j.product_id,'uploads/'||j.import_key||'-'||v.suffix||'.webp',v.position=1,v.alt
FROM catalog_decor_seed_000042 j CROSS JOIN (VALUES
 (1,'01','Vista principal do produto'),(2,'02-produto','Apresentação do produto completo'),(3,'03-detalhe','Textura e acabamento do produto')
) v(position,suffix,alt) ORDER BY j.product_id,v.position;
UPDATE catalog_decor_seed_000042 j SET product_snapshot=to_jsonb(p),
 images_snapshot=(SELECT jsonb_agg(to_jsonb(i) ORDER BY id) FROM product_images i WHERE i.product_id=p.id)
FROM products p WHERE p.id=j.product_id;
COMMIT;
